namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
    public string DepartmentName { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments = new()
    {
        new Department { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new Department { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new Department { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and communication studies." },
        new Department { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new Department { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events, civilizations, and cultural developments." }
    };

    private readonly List<Course> _courses = new()
    {
        new Course { Id = 1, DepartmentId = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience in software engineering and computer science education. She holds a Ph.D. from MIT and has published extensively on programming pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
        new Course { Id = 2, DepartmentId = 1, CourseCode = "CS 201", Title = "Data Structures and Algorithms", Description = "Advanced study of data organization and algorithm design. Covers trees, graphs, sorting, searching, and complexity analysis.", Credits = 4, Schedule = "Tue/Thu 10:30–11:50 AM", InstructorName = "Prof. James Liu", InstructorBio = "Prof. Liu is a renowned researcher in algorithm optimization with over 50 published papers. He previously worked at Google Research.", IsFeatured = true, DepartmentName = "Computer Science" },
        new Course { Id = 3, DepartmentId = 1, CourseCode = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases. SQL, normalization, indexing, and transaction processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez specializes in distributed database systems and has consulted for major tech companies on scalable data solutions.", IsFeatured = false, DepartmentName = "Computer Science" },
        new Course { Id = 4, DepartmentId = 2, CourseCode = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus. Limits, derivatives, and applications of differentiation.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Klein", InstructorBio = "Dr. Klein is an award-winning mathematics educator who has authored three widely-used calculus textbooks.", IsFeatured = true, DepartmentName = "Mathematics" },
        new Course { Id = 5, DepartmentId = 2, CourseCode = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", InstructorName = "Prof. Emily Watson", InstructorBio = "Prof. Watson's research focuses on applied linear algebra in machine learning. She has a joint appointment with the CS department.", IsFeatured = false, DepartmentName = "Mathematics" },
        new Course { Id = 6, DepartmentId = 2, CourseCode = "MATH 305", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Alan Park", InstructorBio = "Dr. Park is a statistician with industry experience in biostatistics and clinical trial design.", IsFeatured = false, DepartmentName = "Mathematics" },
        new Course { Id = 7, DepartmentId = 3, CourseCode = "ENG 101", Title = "English Composition", Description = "Development of writing skills through essays, research papers, and critical analysis of texts.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Diana Foster", InstructorBio = "Prof. Foster is a published author and writing coach with expertise in academic and creative writing.", IsFeatured = false, DepartmentName = "English" },
        new Course { Id = 8, DepartmentId = 3, CourseCode = "ENG 220", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Major authors, movements, and themes.", Credits = 3, Schedule = "Mon/Wed 3:30–4:50 PM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres specializes in 20th-century American fiction and has written critical studies on Hemingway and Faulkner.", IsFeatured = true, DepartmentName = "English" },
        new Course { Id = 9, DepartmentId = 4, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to classical physics.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", InstructorName = "Dr. Karen Nakamura", InstructorBio = "Dr. Nakamura is an experimental physicist who has worked at CERN and specializes in particle physics education.", IsFeatured = false, DepartmentName = "Physics" },
        new Course { Id = 10, DepartmentId = 4, CourseCode = "PHYS 250", Title = "Modern Physics", Description = "Special relativity, quantum mechanics, atomic structure, and nuclear physics.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", InstructorName = "Prof. David Okafor", InstructorBio = "Prof. Okafor's research in quantum computing bridges physics and computer science. He holds multiple patents in quantum device design.", IsFeatured = true, DepartmentName = "Physics" },
        new Course { Id = 11, DepartmentId = 5, CourseCode = "HIST 101", Title = "World Civilizations", Description = "Survey of major world civilizations from ancient times through the early modern period.", Credits = 3, Schedule = "Tue/Thu 2:30–3:50 PM", InstructorName = "Dr. Patricia Hernandez", InstructorBio = "Dr. Hernandez is a specialist in ancient Mediterranean history with archaeological fieldwork experience in Greece and Turkey.", IsFeatured = false, DepartmentName = "History" },
        new Course { Id = 12, DepartmentId = 5, CourseCode = "HIST 315", Title = "The Cold War Era", Description = "Political, social, and cultural history of the Cold War period (1947–1991). Superpower rivalry and its global impact.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", InstructorName = "Prof. Richard Byrne", InstructorBio = "Prof. Byrne is a Cold War historian who has authored two books on US-Soviet relations and consulted for documentary filmmakers.", IsFeatured = false, DepartmentName = "History" }
    };

    private readonly List<EnrollmentRequest> _enrollments = new();

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.ToLower();
            query = query.Where(c =>
                c.Title.ToLower().Contains(term) ||
                c.CourseCode.ToLower().Contains(term) ||
                c.InstructorName.ToLower().Contains(term) ||
                c.DepartmentName.ToLower().Contains(term));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

