@page "/"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<div class="container">
    <div class="hero">
        <h1>University Course Catalog</h1>
        <p>Explore our departments and courses for the upcoming semester.</p>
    </div>

    <section class="section">
        <h2>Featured Courses</h2>
        <div class="course-grid">
            @foreach (var course in _featuredCourses)
            {
                <div class="card">
                    <div class="card-badge">@course.CourseCode</div>
                    <h3>@course.Title</h3>
                    <p class="card-meta">@course.DepartmentName &middot; @course.Credits credits</p>
                    <p>@course.Description[..Math.Min(100, course.Description.Length)]...</p>
                    <a href="/courses/@course.Id" class="btn">View Details</a>
                </div>
            }
        </div>
    </section>

    <section class="section">
        <h2>Departments</h2>
        <div class="dept-grid">
            @foreach (var dept in _departments)
            {
                <a href="/courses?department=@dept.Id" class="dept-card">
                    <h3>@dept.Name</h3>
                    <p class="dept-code">@dept.Code</p>
                    <p>@dept.Description</p>
                </a>
            }
        </div>
    </section>
</div>

@code {
    private List<Course> _featuredCourses = new();
    private List<Department> _departments = new();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetDepartments();
    }
}

@page "/courses"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@rendermode InteractiveServer
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Browse Courses - University Course Catalog</PageTitle>

<div class="container">
    <h1>Browse Courses</h1>

    <div class="filters">
        <input type="text" @bind="SearchTerm" @bind:event="oninput" placeholder="Search by title, code, or instructor..." class="search-input" />
        <select @bind="SelectedDepartment" class="filter-select">
            <option value="">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>

    @if (_courses.Any())
    {
        <div class="course-list">
            @foreach (var course in _courses)
            {
                <div class="course-row">
                    <div class="course-row-info">
                        <span class="course-code">@course.CourseCode</span>
                        <a href="/courses/@course.Id" class="course-title">@course.Title</a>
                        <span class="course-meta">@course.DepartmentName &middot; @course.Credits cr &middot; @course.InstructorName</span>
                    </div>
                    <div class="course-row-schedule">@course.Schedule</div>
                </div>
            }
        </div>
    }
    else
    {
        <p class="no-results">No courses found matching your criteria.</p>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? Department { get; set; }

    private List<Department> _departments = new();
    private List<Course> _courses = new();
    private string _searchTerm = string.Empty;
    private string _selectedDepartment = string.Empty;

    private string SearchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; FilterCourses(); }
    }

    private string SelectedDepartment
    {
        get => _selectedDepartment;
        set { _selectedDepartment = value; FilterCourses(); }
    }

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetDepartments();
        if (Department.HasValue)
            _selectedDepartment = Department.Value.ToString();
        FilterCourses();
    }

    private void FilterCourses()
    {
        int? deptId = int.TryParse(_selectedDepartment, out var id) ? id : null;
        _courses = CatalogService.GetCourses(_searchTerm, deptId);
    }
}

@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course") - University Course Catalog</PageTitle>

<div class="container">
    @if (_course is null)
    {
        <p>Course not found.</p>
    }
    else
    {
        <nav class="breadcrumb">
            <a href="/">Home</a> &rsaquo; <a href="/courses">Courses</a> &rsaquo; @_course.CourseCode
        </nav>

        <div class="course-detail">
            <div class="course-detail-header">
                <h1>@_course.Title</h1>
                <span class="badge">@_course.CourseCode</span>
            </div>

            <div class="detail-grid">
                <div class="detail-main">
                    <h2>Description</h2>
                    <p>@_course.Description</p>

                    <h2>Instructor</h2>
                    <h3>@_course.InstructorName</h3>
                    <p>@_course.InstructorBio</p>
                </div>

                <div class="detail-sidebar">
                    <div class="info-card">
                        <h3>Course Information</h3>
                        <dl>
                            <dt>Department</dt>
                            <dd>@_course.DepartmentName</dd>
                            <dt>Credits</dt>
                            <dd>@_course.Credits</dd>
                            <dt>Schedule</dt>
                            <dd>@_course.Schedule</dd>
                        </dl>
                        <a href="/enroll?course=@_course.Id" class="btn btn-full">Request Enrollment</a>
                    </div>
                </div>
            </div>
        </div>
    }
</div>

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Services
@using UniversityCourseCatalog.Models
@inject CatalogService CatalogService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request - University Course Catalog</PageTitle>

<div class="container">
    <h1>Enrollment Request</h1>

    @if (_submitted)
    {
        <div class="success-message">
            <h2>Request Submitted</h2>
            <p>Your enrollment request has been submitted successfully. You will receive a confirmation via your university email.</p>
            <a href="/courses" class="btn">Back to Courses</a>
        </div>
    }
    else
    {
        <form method="post" @onsubmit="HandleSubmit" @formname="enrollment">
            <AntiforgeryToken />
            <div class="form-group">
                <label for="studentName">Full Name</label>
                <input type="text" id="studentName" name="StudentName" @bind="_model.StudentName" required class="form-input" />
            </div>

            <div class="form-group">
                <label for="studentId">Student ID</label>
                <input type="text" id="studentId" name="StudentId" @bind="_model.StudentId" required class="form-input" placeholder="e.g., STU-12345" />
            </div>

            <div class="form-group">
                <label for="courseId">Course</label>
                <select id="courseId" name="CourseId" @bind="_model.CourseId" required class="form-input">
                    <option value="0" disabled>Select a course...</option>
                    @foreach (var course in _courses)
                    {
                        <option value="@course.Id">@course.CourseCode - @course.Title</option>
                    }
                </select>
            </div>

            <button type="submit" class="btn">Submit Enrollment Request</button>
        </form>
    }
</div>

@code {
    [SupplyParameterFromQuery] public int? Course { get; set; }
    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = new();
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (Course.HasValue && _model.CourseId == 0)
            _model.CourseId = Course.Value;
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.StudentName) || string.IsNullOrWhiteSpace(_model.StudentId) || _model.CourseId == 0)
            return;

        CatalogService.SubmitEnrollment(_model);
        _submitted = true;
    }
}

