 @page "/enroll"
 @using UniversityCourseCatalog.Services
 @using UniversityCourseCatalog.Models
 @inject CatalogService CatalogService
 @inject NavigationManager Navigation

 <PageTitle>Enrollment Request - University Course Catalog</PageTitle>

 <div class="container">
     <h1>Enrollment Request</h1>

     @if (_submitted)
     {
         <div class="success-message">
             <h2>Request Submitted</h2>
             <p>Your enrollment request has been submitted successfully. You will receive a confirmation via your university email.</p>
             <a href="/courses" class="btn">Back to Courses</a>
         </div>
     }
     else
     {
         <form method="post" @onsubmit="HandleSubmit" @formname="enrollment">
             <AntiforgeryToken />
             <div class="form-group">
                 <label for="studentName">Full Name</label>
                 <input type="text" id="studentName" name="StudentName" @bind="_model.StudentName" required class="form-input" />
             </div>

             <div class="form-group">
                 <label for="studentId">Student ID</label>
                 <input type="text" id="studentId" name="StudentId" @bind="_model.StudentId" required class="form-input" placeholder="e.g., STU-12345" />
             </div>

             <div class="form-group">
                 <label for="courseId">Course</label>
                 <select id="courseId" name="CourseId" @bind="_model.CourseId" required class="form-input">
                     <option value="0" disabled>Select a course...</option>
                     @foreach (var course in _courses)
                     {
                         <option value="@course.Id">@course.CourseCode - @course.Title</option>
                     }
                 </select>
             </div>

             <button type="submit" class="btn">Submit Enrollment Request</button>
         </form>
     }
 </div>

 @code {
     [SupplyParameterFromQuery] public int? Course { get; set; }
     [SupplyParameterFromForm] private EnrollmentRequest? _model { get; set; }

     private EnrollmentRequest Model => _model ??= new();

     private List<Course> _courses = new();
     private bool _submitted;

     protected override void OnInitialized()
     {
         _courses = CatalogService.GetCourses();
         if (Course.HasValue && _model.CourseId == 0)
             _model.CourseId = Course.Value;
     }

     private void HandleSubmit()
     {
         if (string.IsNullOrWhiteSpace(_model.StudentName) || string.IsNullOrWhiteSpace(_model.StudentId) || _model.CourseId == 0)
             return;

         CatalogService.SubmitEnrollment(_model);
         _submitted = true;
     }
 }

